<script setup>
import {ref,computed,onMounted,onBeforeUnmount,nextTick} from 'vue'
import {Bot,MessageCircle,Phone,FlaskConical,ArrowRight,RefreshCw,X,Clock,Users,AlertCircle,CheckCircle2,Settings2} from 'lucide-vue-next'
const props=defineProps({canConfigure:Boolean})
const emit=defineEmits(['configure'])
const data=ref(null),busy=ref(false),error=ref(''),auto=ref(false),filters=ref({scope:'production',from:'',to:'',agent_id:'',channel:'',outcome:'',page:1})
const detail=ref(null),detailId=ref(null),detailPage=ref(1),detailBusy=ref(false),detailError=ref(''),modal=ref(null)
const labels={open:'Em andamento',connecting:'Conectando',closing:'Encerrando',transferring:'Transferência solicitada',transferred:'Transferência solicitada',handoff:'Passagem humana',stop:'Interrupção solicitada',closed:'Encerrada',failed:'Falha'}
const channelLabels={whatsapp:'WhatsApp · texto',phone:'Telefonia SIP · voz',text:'Teste de texto',voice:'Teste de voz'}
const outcomes={active:'Em andamento',handoff:'Passagens solicitadas',failure:'Com falhas',stop:'Interrupções solicitadas',closed:'Encerradas',expired:'Prazo excedido'}
const scopeChannels=computed(()=>filters.value.scope==='production'?['whatsapp','phone']:['text','voice'])
const maxDay=computed(()=>Math.max(1,...(data.value?.series||[]).map(d=>d.total)))
const maxChannel=computed(()=>Math.max(1,...(data.value?.channels||[]).map(d=>d.total)))
const cards=computed(()=>data.value?[
 {key:'',label:'Conversas',value:data.value.summary.sessions,icon:Bot},
 {key:'active',label:'Em andamento',value:data.value.summary.active,icon:MessageCircle},
 {key:'handoff',label:'Passagens solicitadas',value:data.value.summary.handoff,icon:Users},
 {key:'failure',label:'Com falhas',value:data.value.summary.failure,icon:AlertCircle},
 {key:'stop',label:'Interrupções solicitadas',value:data.value.summary.stop,icon:CheckCircle2},
 {key:'expired',label:'Prazo excedido',value:data.value.summary.expired,icon:Clock}
]:[])
let timer,request=0,detailRequest=0,opener
function stamp(v){return v?new Date(/[zZ]|[+-]\d\d:\d\d$/.test(v)?v:v.replace(' ','T')+'Z').toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}):'—'}
function money(v){return v==null?'Consultar provedor':'US$ '+Number(v).toFixed(6)}
async function api(path){const r=await fetch('/api/ai/supervision'+path,{headers:{Accept:'application/json'},cache:'no-store'});const d=await r.json();if(!r.ok)throw Error(d.errors?Object.values(d.errors).flat().join(' · '):d.message||'Não foi possível consultar.');return d}
async function load(){const n=++request;busy.value=true;error.value='';try{const q=new URLSearchParams(Object.entries(filters.value).filter(([,v])=>v!==''));const d=await api('?'+q);if(n!==request)return;data.value=d;filters.value.from=d.filters.from;filters.value.to=d.filters.to}catch(e){if(n===request)error.value='Não foi possível atualizar. '+e.message}finally{if(n===request)busy.value=false}}
function apply(){filters.value.page=1;load()}
function changeScope(scope){filters.value.scope=scope;filters.value.channel='';filters.value.outcome='';apply()}
function outcome(key){filters.value.outcome=key;apply()}
function day(date){filters.value.from=date;filters.value.to=date;apply()}
function recent(){filters.value.from='';filters.value.to='';filters.value.outcome='';filters.value.channel='';apply()}
async function open(id,page=1){if(detailId.value!==id){opener=document.activeElement;detail.value=null}detailId.value=id;detailPage.value=page;detailError.value='';detailBusy.value=true;const n=++detailRequest;await nextTick();modal.value?.querySelector('button')?.focus();try{const d=await api('/sessions/'+id+'?page='+page);if(n===detailRequest)detail.value=d}catch(e){if(n===detailRequest)detailError.value=e.message}finally{if(n===detailRequest)detailBusy.value=false}}
function close(){detailRequest++;detailId.value=null;detail.value=null;opener?.focus()}
function trap(event){const items=[...modal.value.querySelectorAll('button:not(:disabled),a[href],input,select,[tabindex="0"]')];if(!items.length)return;const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}
onMounted(()=>{load();timer=setInterval(()=>{if(auto.value&&!busy.value&&!detailId.value&&!document.hidden)load()},15000)})
onBeforeUnmount(()=>{clearInterval(timer);request++;detailRequest++})
</script>
<template>
 <div class="ais">
  <header class="ais-heading"><div><span class="eyebrow">CADA CONVERSA, VISÍVEL</span><h1>Supervisão de IA</h1><p>Acompanhe o atendimento e encontre o que precisa da equipe.</p></div><div class="ais-actions"><button v-if="props.canConfigure" class="secondary" @click="emit('configure')"><Settings2 :size="16"/>Configurar agentes</button><button class="secondary" @click="load" :disabled="busy"><RefreshCw :size="16"/>{{busy?'Atualizando…':'Atualizar'}}</button></div></header>
  <div class="ais-scope" aria-label="Origem das conversas"><button :class="{active:filters.scope==='production'}" @click="changeScope('production')"><MessageCircle :size="17"/>Atendimento real</button><button :class="{active:filters.scope==='tests'}" @click="changeScope('tests')"><FlaskConical :size="17"/>Laboratório</button></div>
  <p class="ais-help">{{filters.scope==='production'?'WhatsApp e telefonia SIP. Os testes do laboratório ficam separados.':'Simulações de regras e testes com IA. Estes resultados não representam atendimento a clientes.'}}</p>
  <form class="ais-filters" @submit.prevent="apply"><label>De<input type="date" v-model="filters.from" required></label><label>Até<input type="date" v-model="filters.to" required></label><label>Agente de IA<select v-model="filters.agent_id"><option value="">Todos os agentes</option><option v-for="a in data?.agents||[]" :key="a.id" :value="a.id">{{a.name}}</option></select></label><label>Canal<select v-model="filters.channel"><option value="">Todos os canais</option><option v-for="c in scopeChannels" :key="c" :value="c">{{channelLabels[c]}}</option></select></label><button class="primary" :disabled="busy">Aplicar filtros</button></form>
  <p class="ais-help">Filtro pelo início da conversa. Resultados e consumo são acumulados até a coleta.</p><div class="ais-update"><span>{{data?'Última atualização: '+stamp(data.as_of):'Carregando conversas…'}} · horário de Brasília</span><label><input type="checkbox" v-model="auto">Atualizar a cada 15 segundos</label></div>
  <div v-if="error" class="ais-error" role="alert">{{error}} <span v-if="data">Os dados abaixo são da última consulta bem-sucedida.</span></div>
  <template v-if="data">
   <div class="ais-cards"><button v-for="c in cards" :key="c.key" :class="['ais-card',{selected:filters.outcome===c.key}]" @click="outcome(c.key)"><span><component :is="c.icon" :size="17"/>{{c.label}}</span><strong>{{c.value}}</strong><small>Ver conversas <ArrowRight :size="12"/></small></button></div>
   <div class="ais-filter-note"><span v-if="filters.outcome">Filtro: <b>{{outcomes[filters.outcome]}}</b> <button @click="outcome('')">Limpar resultado</button></span><span>Uma conversa pode ter falha e passagem humana. Solicitação de transferência não confirma atendimento.</span></div>
   <div class="ais-charts"><article><div class="ais-section-title"><h2>Conversas por dia</h2><button @click="recent">Últimos 7 dias</button></div><p class="ais-help">Clique em uma barra para consultar aquele dia.</p><div class="ais-daily" v-if="data.summary.sessions"><button v-for="d in data.series" :key="d.date" @click="day(d.date)" :aria-label="d.date+': '+d.total+' conversas'"><strong>{{d.total}}</strong><span class="ais-column" :style="{height:(8+95*d.total/maxDay)+'px'}"/><small>{{d.date.slice(8)}}/{{d.date.slice(5,7)}}</small></button></div><div v-else class="ais-chart-empty">As conversas aparecerão aqui conforme forem registradas.</div></article><article><h2>Por canal</h2><div class="ais-channel-bars" v-if="data.channels.length"><button v-for="c in data.channels" :key="c.channel" @click="filters.channel=c.channel;apply()"><span>{{channelLabels[c.channel]}}<strong>{{c.total}}</strong></span><i><b :style="{width:(100*c.total/maxChannel)+'%'}"/></i></button></div><div v-else class="ais-chart-empty">Nenhum canal com conversas neste filtro.</div></article></div>
   <div class="ais-measures"><article><span>Texto · consumo estimado</span><strong>{{money(data.summary.text_estimated_usd)}}</strong><small>{{data.summary.input_tokens}} tokens de entrada · {{data.summary.output_tokens}} de saída. Exclui infraestrutura própria, voz, telefonia e WhatsApp.</small></article><article><span>Texto · processamento médio</span><strong>{{data.summary.text_latency_ms==null?'Sem amostras':(data.summary.text_latency_ms/1000).toFixed(2)+' s'}}</strong><small>{{data.summary.text_latency_samples}} respostas concluídas em sessões com IA. Inclui regras locais; não mede áudio.</small></article><article><span>Voz · {{data.summary.voice_sessions}} sessões</span><strong>Consumo no provedor</strong><small>O custo e a latência de áudio ainda não são consolidados neste painel.</small></article></div>
   <section class="ais-list"><div class="ais-section-title"><h2>Conversas <small>{{data.sessions.total}}</small></h2><span class="ais-help">Encerrada não significa problema resolvido.</span></div><div class="ais-table-scroll" v-if="data.sessions.data.length"><table><thead><tr><th>Agente / início</th><th>Canal</th><th>Situação</th><th>Consumo estimado</th><th>Detalhes</th></tr></thead><tbody><tr v-for="s in data.sessions.data" :key="s.id"><td><strong>{{s.agent_name||'Agente'}}</strong><small>{{stamp(s.created_at)}}</small></td><td>{{channelLabels[s.channel]}}<small v-if="filters.scope==='tests'">{{s.mode==='local'?'Simulação gratuita':'API premium'}}</small></td><td><span :class="['ais-pill',{warn:s.expired||s.status==='failed'}]">{{s.expired?'Prazo excedido':labels[s.status]||s.status}}</span></td><td>{{s.mode==='local'?'Sem cobrança':s.provider==='qwen'?'Infraestrutura própria':money(s.estimated_usd)}}</td><td><button class="secondary" @click="open(s.id)" :aria-label="'Detalhes de '+(s.agent_name||'agente')+' em '+stamp(s.created_at)">Ver conversa <ArrowRight :size="14"/></button></td></tr></tbody></table></div><div v-else class="ais-empty"><Bot :size="35"/><h3>Nenhuma conversa neste filtro</h3><p>{{filters.scope==='production'?'Quando os canais forem ativados, acompanhe aqui as conversas reais.':'Execute um teste no laboratório para consultar seu resultado aqui.'}}</p><button v-if="filters.scope==='production'" class="secondary" @click="changeScope('tests')">Ver laboratório</button></div><footer class="ais-pagination"><button class="secondary" :disabled="busy||data.sessions.current_page<=1" @click="filters.page--;load()">Anterior</button><span>{{data.sessions.current_page}} / {{data.sessions.last_page}}</span><button class="secondary" :disabled="busy||data.sessions.current_page>=data.sessions.last_page" @click="filters.page++;load()">Próxima</button></footer></section>
   <details class="ais-readiness"><summary>Preparação do ambiente e limites da leitura</summary><div class="ais-tags"><span>{{data.readiness.published_agents}} agentes publicados</span><span>{{data.readiness.configured?'Conexão cadastrada':'Conexão a cadastrar'}}</span><span>{{data.readiness.consumption_enabled?'Consumo da API autorizado':'Consumo da API desativado'}}</span><span>{{data.readiness.voice_worker_ready?'Serviço de voz conectado':'Serviço de voz indisponível'}}</span></div><p>Esses sinais não comprovam homologação da voz ou ativação dos canais. O histórico tem retenção de 30 dias e pode ficar incompleto para períodos mais antigos. Não calculamos pontuação emocional nem aprovação automática da qualidade.</p></details>
  </template>
  <div v-if="detailId" class="ais-overlay"><section ref="modal" class="ais-modal" role="dialog" aria-modal="true" aria-labelledby="ais-detail-title" @keydown.tab="trap" @keydown.esc="close"><header><div><span class="eyebrow">CONTEXTO DO ATENDIMENTO</span><h2 id="ais-detail-title">{{detail?.profile.name||'Detalhes da conversa'}}</h2></div><button aria-label="Fechar conversa" @click="close"><X :size="22"/></button></header><p v-if="detailBusy" role="status">Carregando detalhes…</p><p v-if="detailError" class="ais-error" role="alert">{{detailError}}</p><template v-if="detail"><div class="ais-tags"><span>{{channelLabels[detail.session.channel]}}</span><span>{{detail.session.mode==='local'?'Simulação gratuita':filters.scope==='tests'?'Teste com IA':'Atendimento real'}}</span><span>{{detail.session.expired?'Prazo excedido':labels[detail.session.status]||detail.session.status}}</span><span>{{detail.profile.language}} · revisão {{detail.profile.revision}}</span><span v-if="detail.profile.adaptive_conversation">Atendimento adaptativo</span></div><p class="ais-help">Início: {{stamp(detail.session.created_at)}} · {{detail.session.provider==='qwen'?'Infraestrutura própria':money(detail.session.estimated_usd)}}</p><article class="ais-summary"><h3>Resumo registrado</h3><p>{{detail.session.summary||'Ainda não há resumo registrado.'}}</p><small>Confira o conteúdo da conversa antes de tomar uma decisão.</small></article><div v-if="detail.transfers.length" class="ais-notice"><strong>Transferência SIP</strong><p v-for="(t,i) in detail.transfers" :key="i">{{stamp(t.requested_at)}} · {{t.provider_accepted?'Solicitação aceita pelo provedor; atendimento humano não confirmado.':'Solicitação sem confirmação do provedor.'}}</p></div><details v-if="detail.deliveries.length"><summary>Processamento do WhatsApp · últimos {{detail.deliveries.length}} eventos</summary><p v-for="(d,i) in detail.deliveries" :key="i">{{stamp(d.created_at)}} · {{({pending:'Pendente',processing:'Processando',sent:'Resposta enviada ao canal',handoff:'Passagem humana',stop:'Interrupção',failed:'Falha',unknown:'Revisão necessária'})[d.status]||d.status}}<br>{{d.reason}}</p><p class="ais-help">Envio ao canal não confirma entrega nem leitura no celular.</p></details><p v-if="['voice','phone'].includes(detail.session.channel)" class="ais-notice">Não há gravação de áudio neste histórico. {{detail.session.channel==='phone'?'As falas registradas são do agente; não há transcrição do cliente.':'A transcrição do teste de voz fica somente no navegador durante o teste.'}}</p><div class="ais-transcript"><article v-for="t in detail.turns.data" :key="t.id"><p v-if="t.input" class="ais-user"><small>Cliente / teste · {{stamp(t.created_at)}}</small>{{t.input}}</p><p class="ais-assistant"><small>Agente · {{({completed:'Concluída',failed:'Falha',processing:'Processando'})[t.status]||t.status}}{{t.latency_ms!=null?' · '+t.latency_ms+' ms':''}}</small>{{t.output||'Resposta ainda não registrada.'}}<span v-if="t.action&&t.action!=='reply'" class="ais-pill">{{t.action==='handoff'?'Passagem humana':'Interrupção solicitada'}}</span></p></article><p v-if="!detail.turns.total" class="ais-help">Nenhuma fala armazenada para esta sessão. O conteúdo também pode ter expirado pela retenção.</p></div><footer class="ais-pagination"><button class="secondary" :disabled="detailBusy||detail.turns.current_page<=1" @click="open(detailId,detailPage-1)">Falas anteriores</button><span>{{detail.turns.current_page}} / {{detail.turns.last_page}}</span><button class="secondary" :disabled="detailBusy||detail.turns.current_page>=detail.turns.last_page" @click="open(detailId,detailPage+1)">Próximas falas</button></footer></template></section></div>
 </div>
</template>
<style scoped>
.ais{color:#283a30;min-width:0}.ais-heading,.ais-actions,.ais-section-title,.ais-update{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}.ais-heading{margin:20px 0 24px}.ais-heading p,.ais-help{color:#758273;font-size:12px;line-height:1.8}.ais-actions{justify-content:flex-start}.ais-scope{display:inline-flex;max-width:100%;flex-wrap:wrap;gap:6px;padding:6px;border:1px solid #e0e5da;background:#edefe7;border-radius:14px}.ais-scope button{padding:12px 18px;gap:9px;border-radius:9px;font-size:12px}.ais-scope button.active{background:white;color:#886321;box-shadow:0 3px 12px #20321a0a}.ais-filters{display:grid;grid-template-columns:1fr 1fr 1.4fr 1.3fr auto;gap:12px;align-items:end;background:white;border:1px solid #dde4d7;padding:20px;border-radius:16px;margin:20px 0}.ais-filters label{font-size:12px;min-width:0}.ais-filters input,.ais-filters select{width:100%;min-width:0}.ais-update{font-size:11px;color:#7c8774;margin:18px 0}.ais-update label{display:flex;flex-direction:row;gap:8px;align-items:center}.ais-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.ais-card{display:flex;flex-direction:column;align-items:flex-start;gap:16px;background:#fff;border:1px solid #dfe5d8;border-radius:18px;padding:22px;text-align:left}.ais-card.selected{border-color:#bf9540;box-shadow:0 0 0 2px #d9b56122}.ais-card>span{display:flex;gap:9px;color:#75816f;font-size:12px}.ais-card svg{color:#b18a35}.ais-card strong{font-size:32px;line-height:1;color:#344c39}.ais-card small{display:flex;gap:8px;font-size:10px;color:#8a7c59}.ais-filter-note{font-size:11px;color:#7c826e;margin:17px 0;display:flex;flex-direction:column;gap:8px}.ais-filter-note button{color:#9c731b;text-decoration:underline;margin-left:12px}.ais-charts{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(0,1fr);gap:18px}.ais-charts article,.ais-list{min-width:0;border:1px solid #dfe4d8;background:#fff;border-radius:18px;padding:24px}.ais h2{font-size:19px}.ais-section-title h2 small{font-size:12px;color:#8b947e;margin-left:10px}.ais-section-title>button{font-size:11px;color:#9a752c}.ais-daily{display:flex;align-items:flex-end;gap:10px;overflow-x:auto;min-height:155px;padding-bottom:8px}.ais-daily button{display:flex;flex:1;min-width:36px;align-items:center;flex-direction:column;gap:7px;font-size:10px}.ais-daily strong{font-size:11px;color:#5b7159}.ais-column{display:block;width:80%;max-width:50px;border-radius:7px 7px 3px 3px;background:linear-gradient(#cfb269,#ab893f)}.ais-daily button:hover .ais-column{background:#426b56}.ais-channel-bars{display:flex;flex-direction:column;gap:22px;margin-top:25px}.ais-channel-bars button{display:block;width:100%;text-align:left}.ais-channel-bars span{display:flex;justify-content:space-between;font-size:12px}.ais-channel-bars i{display:block;background:#edf0e7;border-radius:10px;height:12px;margin-top:10px;overflow:hidden}.ais-channel-bars b{display:block;background:#557a5e;height:100%;border-radius:10px}.ais-chart-empty{padding:45px 0;color:#89917f;font-size:12px;text-align:center}.ais-measures{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px;margin:20px 0}.ais-measures article{display:flex;flex-direction:column;gap:12px;border:1px solid #e1e6d9;border-radius:14px;background:#f1f4ec;padding:20px}.ais-measures span{font-size:12px;color:#74816b}.ais-measures strong{font-size:20px}.ais-measures small{font-size:11px;color:#7b8570;line-height:1.8}.ais-table-scroll{overflow-x:auto;margin:20px -8px 0}.ais table{width:100%;font-size:12px}.ais th{font-size:10px;letter-spacing:.06em;text-transform:uppercase;color:#8a927e;text-align:left;padding:15px 10px;background:#f7f8f3}.ais td{padding:17px 10px;border-bottom:1px solid #e8ebdf}.ais td small{display:block;font-size:10px;color:#85907b;margin-top:6px}.ais-pill{display:inline-block;padding:6px 9px;border-radius:16px;background:#eaf2e9;color:#537052;font-size:10px;white-space:nowrap}.ais-pill.warn{background:#fff0db;color:#a67528}.ais-pagination{display:flex;gap:14px;justify-content:center;align-items:center;margin-top:22px;font-size:11px;color:#8b927f;flex-wrap:wrap}.ais-empty{display:flex;flex-direction:column;align-items:center;text-align:center;padding:35px 12px;gap:12px;color:#819075}.ais-empty h3{font-size:19px}.ais-empty p{font-size:12px}.ais-readiness{margin-top:24px;padding:0 20px;border:1px solid #dfe5d8;border-radius:14px;background:#f8f9f4}.ais summary{cursor:pointer;color:#856c32;font-size:12px;padding:17px 0}.ais-readiness p{font-size:12px;color:#7d8872;line-height:1.8}.ais-tags{display:flex;gap:8px;flex-wrap:wrap}.ais-tags span{background:#f2f2e9;color:#7c805f;font-size:10px;padding:7px 10px;border-radius:20px}.ais-error{background:#fff0ed;color:#ac4835;border-radius:12px;padding:16px;font-size:12px;line-height:1.8;margin:15px 0}.ais-overlay{position:fixed;inset:0;background:#15291f66;backdrop-filter:blur(4px);z-index:135;display:flex;align-items:center;justify-content:center;padding:20px}.ais-modal{background:white;width:760px;max-width:100%;max-height:92vh;overflow:auto;border-radius:22px;padding:28px;box-shadow:0 22px 80px #18352833}.ais-modal header{display:flex;justify-content:space-between;gap:15px;margin-bottom:20px}.ais-modal header h2{font-size:23px;margin-top:10px}.ais-modal header>button{align-self:flex-start}.ais-modal p{font-size:12px;line-height:1.8;overflow-wrap:anywhere}.ais-summary{background:#f4f6ee;border-radius:13px;padding:18px;margin:20px 0}.ais-summary h3{font-size:13px}.ais-summary small{color:#8a907b;font-size:10px}.ais-notice{padding:14px;border:1px solid #e3e6d9;border-radius:12px;color:#7d8169;font-size:12px}.ais-transcript article{display:flex;flex-direction:column;gap:8px}.ais-transcript p{max-width:94%;padding:14px 17px;border-radius:14px;white-space:pre-wrap;margin:8px 0}.ais-user{align-self:flex-end;background:#e9f1e8}.ais-assistant{align-self:flex-start;background:#f3f4ed}.ais-transcript small{display:block;font-size:10px;color:#85917a;margin-bottom:8px}.ais-transcript .ais-pill{display:block;width:fit-content;margin-top:9px}@media(max-width:1000px){.ais-filters{grid-template-columns:1fr 1fr}.ais-charts{grid-template-columns:minmax(0,1fr)}.ais-measures{grid-template-columns:1fr}.ais-cards{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.ais-heading h1{font-size:27px}.ais-filters{grid-template-columns:1fr;padding:16px}.ais-cards{gap:10px}.ais-card{padding:15px}.ais-card>span{flex-direction:column;line-height:1.6}.ais-charts article,.ais-list{padding:18px 14px}.ais-scope button{padding:10px;font-size:11px}.ais-overlay{padding:10px}.ais-modal{padding:20px 16px}.ais-modal header h2{font-size:20px}.ais-update{align-items:flex-start;flex-direction:column}.ais-table-scroll{margin-left:0;margin-right:0}.ais-measures strong{overflow-wrap:anywhere}}
</style>
